#pragma once
#include <windows.h>
#include <tlhelp32.h>
#include <array>
#include <cstdint>
#include <cwchar>
#include <vector>

namespace off {
inline constexpr const wchar_t* process = L"game.exe";
inline constexpr const wchar_t* module = L"game.exe";
inline constexpr uintptr_t viewMatrix = 0x0;
inline constexpr uintptr_t entityList = 0x0;
inline constexpr uintptr_t localPlayer = 0x0;
inline constexpr uintptr_t entityStride = 0x8;
inline constexpr int maxEntities = 64;
inline constexpr uintptr_t health = 0x0;
inline constexpr uintptr_t team = 0x0;
inline constexpr uintptr_t head = 0x0;
}

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };
using ViewMatrix = std::array<float, 16>;

struct Player {
  uintptr_t addr = 0;
  int health = 0;
  int team = 0;
  Vec3 head{};
};

class Memory {
public:
  ~Memory() { if (handle_) CloseHandle(handle_); }

  bool attach(const wchar_t* proc, const wchar_t* mod) {
    pid_ = findPid(proc);
    if (!pid_) return false;
    if (!handle_) handle_ = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid_);
    if (!handle_) return false;
    base_ = findModule(mod);
    return base_ != 0;
  }

  template <class T>
  T read(uintptr_t addr) const {
    T value{};
    ReadProcessMemory(handle_, reinterpret_cast<LPCVOID>(addr), &value, sizeof(T), nullptr);
    return value;
  }

  ViewMatrix viewMatrix() const { return read<ViewMatrix>(base_ + off::viewMatrix); }

  Player readPlayer(uintptr_t addr) const {
    Player p;
    p.addr = addr;
    if (!addr) return p;
    p.health = read<int>(addr + off::health);
    p.team = read<int>(addr + off::team);
    p.head = read<Vec3>(addr + off::head);
    return p;
  }

  Player localPlayer() const { return readPlayer(read<uintptr_t>(base_ + off::localPlayer)); }

  std::vector<Player> entities() const {
    std::vector<Player> out;
    uintptr_t list = base_ + off::entityList;
    for (int i = 0; i < off::maxEntities; ++i) {
      uintptr_t addr = read<uintptr_t>(list + i * off::entityStride);
      if (!addr) continue;
      Player p = readPlayer(addr);
      if (p.health > 0) out.push_back(p);
    }
    return out;
  }

private:
  static DWORD findPid(const wchar_t* name) {
    DWORD pid = 0;
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W e{};
    e.dwSize = sizeof(e);
    for (BOOL ok = Process32FirstW(snap, &e); ok; ok = Process32NextW(snap, &e))
      if (!_wcsicmp(e.szExeFile, name)) { pid = e.th32ProcessID; break; }
    CloseHandle(snap);
    return pid;
  }

  uintptr_t findModule(const wchar_t* name) const {
    uintptr_t addr = 0;
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid_);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    MODULEENTRY32W e{};
    e.dwSize = sizeof(e);
    for (BOOL ok = Module32FirstW(snap, &e); ok; ok = Module32NextW(snap, &e))
      if (!_wcsicmp(e.szModule, name)) { addr = reinterpret_cast<uintptr_t>(e.modBaseAddr); break; }
    CloseHandle(snap);
    return addr;
  }

  DWORD pid_ = 0;
  HANDLE handle_ = nullptr;
  uintptr_t base_ = 0;
};

inline bool worldToScreen(const Vec3& p, const ViewMatrix& m, int w, int h, Vec2& out) {
  float cx = m[0] * p.x + m[1] * p.y + m[2] * p.z + m[3];
  float cy = m[4] * p.x + m[5] * p.y + m[6] * p.z + m[7];
  float cw = m[12] * p.x + m[13] * p.y + m[14] * p.z + m[15];
  if (cw < 0.01f) return false;
  out.x = (w / 2.0f) * (1.0f + cx / cw);
  out.y = (h / 2.0f) * (1.0f - cy / cw);
  return true;
}

#include "mem.h"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <optional>
#include <thread>

namespace cfg {
constexpr const wchar_t* windowTitle = L"Game";
constexpr float fovRadius = 240.0f;
constexpr float sensitivity = 1.0f;
constexpr float easeDuration = 0.18f;
constexpr int aimKey = VK_RBUTTON;
constexpr int exitKey = VK_END;
constexpr auto tick = std::chrono::milliseconds(5);
}

struct Screen {
  int w, h;
  Vec2 center;
};

static std::optional<Screen> gameScreen() {
  HWND hwnd = FindWindowW(nullptr, cfg::windowTitle);
  if (!hwnd) return std::nullopt;
  RECT rc;
  if (!GetClientRect(hwnd, &rc)) return std::nullopt;
  int w = rc.right - rc.left, h = rc.bottom - rc.top;
  return Screen{ w, h, { w / 2.0f, h / 2.0f } };
}

static std::optional<Vec2> pickTarget(const Memory& mem, const Screen& s) {
  Player local = mem.localPlayer();
  if (!local.addr || local.health <= 0) return std::nullopt;
  ViewMatrix vm = mem.viewMatrix();
  std::optional<Vec2> best;
  float bestDist = cfg::fovRadius;
  for (const Player& p : mem.entities()) {
    if (p.addr == local.addr || p.team == local.team) continue;
    Vec2 sp;
    if (!worldToScreen(p.head, vm, s.w, s.h, sp)) continue;
    float d = std::hypot(sp.x - s.center.x, sp.y - s.center.y);
    if (d < bestDist) { bestDist = d; best = sp; }
  }
  return best;
}

static float easeOutCubic(float t) { return 1.0f - std::pow(1.0f - t, 3.0f); }

class Mover {
public:
  void reset() { active_ = false; carryX_ = carryY_ = 0.0f; }

  void step(Vec2 delta) {
    auto now = clock::now();
    if (!active_) { active_ = true; start_ = now; prevE_ = 0.0f; }
    float t = std::min(1.0f, std::chrono::duration<float>(now - start_).count() / cfg::easeDuration);
    float e = easeOutCubic(t);
    float frac = prevE_ < 1.0f ? (e - prevE_) / (1.0f - prevE_) : 1.0f;
    prevE_ = e;
    float mx = delta.x * frac * cfg::sensitivity + carryX_;
    float my = delta.y * frac * cfg::sensitivity + carryY_;
    LONG ix = static_cast<LONG>(mx), iy = static_cast<LONG>(my);
    carryX_ = mx - ix;
    carryY_ = my - iy;
    if (!ix && !iy) return;
    INPUT in{};
    in.type = INPUT_MOUSE;
    in.mi.dx = ix;
    in.mi.dy = iy;
    in.mi.dwFlags = MOUSEEVENTF_MOVE;
    SendInput(1, &in, sizeof(in));
  }

private:
  using clock = std::chrono::steady_clock;
  bool active_ = false;
  clock::time_point start_{};
  float prevE_ = 0.0f, carryX_ = 0.0f, carryY_ = 0.0f;
};

int main() {
  Memory mem;
  while (!mem.attach(off::process, off::module)) {
    std::puts("waiting for process...");
    std::this_thread::sleep_for(std::chrono::seconds(1));
  }
  std::puts("attached. hold RMB to aim, END to quit.");

  Mover mover;
  while (!(GetAsyncKeyState(cfg::exitKey) & 0x8000)) {
    std::this_thread::sleep_for(cfg::tick);
    auto screen = gameScreen();
    if (!screen || !(GetAsyncKeyState(cfg::aimKey) & 0x8000)) { mover.reset(); continue; }
    auto target = pickTarget(mem, *screen);
    if (!target) { mover.reset(); continue; }
    mover.step({ target->x - screen->center.x, target->y - screen->center.y });
  }
  return 0;
}
